<script setup>
import { computed,onMounted,ref } from 'vue'
import { listProducts,updateProductStock } from '../services/api'
const props=defineProps({user:{type:Object,required:true},token:{type:String,required:true}})
const emit=defineEmits(['logout'])
const products=ref([]),search=ref(''),drafts=ref({}),loading=ref(false),busyId=ref(null),error=ref(''),success=ref('')
const displayName=[props.user.first_name,props.user.first_surname].filter(Boolean).join(' ')||'Encargado de bodega'
const filtered=computed(()=>{const q=search.value.trim().toLocaleLowerCase();return products.value.filter(p=>!q||p.name.toLocaleLowerCase().includes(q))})
const money=v=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(Number(v||0))
async function load(){loading.value=true;error.value='';try{products.value=await listProducts();drafts.value=Object.fromEntries(products.value.map(p=>[p.id,String(p.stock)]))}catch(e){error.value=e.message||'No fue posible cargar el inventario.'}finally{loading.value=false}}
async function save(product){const stock=Number(drafts.value[product.id]);if(!Number.isFinite(stock)||stock<0){error.value='Ingresa una existencia válida.';return}busyId.value=product.id;error.value='';success.value='';try{const updated=await updateProductStock(product.id,stock,props.token);const i=products.value.findIndex(p=>p.id===product.id);if(i!==-1)products.value[i]=updated;drafts.value[product.id]=String(updated.stock);success.value=`Existencias de ${updated.name} actualizadas.`}catch(e){error.value=e.message||'No fue posible actualizar las existencias.'}finally{busyId.value=null}}
onMounted(load)
</script>
<template><main class="operations-shell"><header class="operations-header"><a class="customer-brand" href="#" @click.prevent="load"><span class="customer-brand-mark">♧</span><span><strong>Canasta Express</strong><small>Legumbrería &amp; Verdulería Online</small></span></a><div class="operations-user"><span>Hola, {{displayName}}</span><button @click="emit('logout')">Salir</button></div></header><section class="operations-page"><div class="operations-title-row"><div><p class="operations-kicker">INVENTARIO · BODEGA</p><h1>Control de existencias</h1><p>Consulta el inventario y registra las cantidades disponibles de cada producto.</p></div><button class="operations-refresh" @click="load">↻ Actualizar</button></div><form class="stock-search" @submit.prevent><input v-model="search" type="search" placeholder="Buscar producto por nombre"><span>{{filtered.length}} productos</span></form><p v-if="error" class="operations-alert error">{{error}}</p><p v-if="success" class="operations-alert success">{{success}}</p><div v-if="loading" class="operations-empty">Cargando inventario…</div><div v-else-if="filtered.length" class="stock-table-wrap"><table class="stock-table"><thead><tr><th>Producto</th><th>Precio de venta</th><th>Existencias actuales</th><th>Actualizar cantidad</th><th></th></tr></thead><tbody><tr v-for="product in filtered" :key="product.id"><td><div class="stock-product"><img v-if="product.image_path" :src="API_BASE_URL+product.image_path" :alt="product.name"><span v-else>♧</span><strong>{{product.name}}</strong></div></td><td>{{money(product.price)}}</td><td>{{product.stock}} {{product.unit_of_measure}}</td><td><input v-model="drafts[product.id]" type="number" min="0" max="9999999.999" step="0.001" :aria-label="'Nueva existencia de '+product.name"></td><td><button class="stock-save" :disabled="busyId===product.id || String(product.stock)===drafts[product.id]" @click="save(product)">{{busyId===product.id?'Guardando…':'Guardar'}}</button></td></tr></tbody></table></div><div v-else class="operations-empty">No se encontraron productos.</div></section></main></template>